{
  "name": "@route_33/opencode",
  "version": "0.4.6",
  "type": "module",
  "license": "SEE LICENSE IN LICENSE",
  "description": "opencode provider plugin for the route33.ai AI gateway \u2014 key-scoped model discovery, cost/limit enrichment, auth, and the key-setup wizard.",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Cronos-AI-Lab/harness-bench.git",
    "directory": "packages/integrations/opencode-route33"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "route33"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui/index.d.ts",
      "import": "./dist/tui/index.js"
    }
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "files": [
    "dist",
    "docs"
  ],
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.0 <2.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.12",
    "@types/node": "^22.10.7",
    "tsup": "^8.3.5",
    "typescript": "^5.7.3",
    "vitest": "^3.0.5"
  },
  "scripts": {
    "build": "tsup",
    "prepack": "bun run build",
    "bundle": "tsup",
    "bundle:watch": "tsup --watch",
    "verify:bundle": "bun run scripts/verify-bundle.ts",
    "test": "vitest run && bun run verify:bundle",
    "typecheck": "tsc --noEmit"
  }
}
